sql_query:
SELECT "Trial name"
FROM clinical_trials
WHERE "Cancer type" = 'Bladder' AND "Included in MA" = 'Yes' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Trial name" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Bladder' AND "Included in MA" = 'Yes' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_trial_acronym(source_value) AS "trial_acronym"
FROM base;
